package com.dbdriver.core;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import java.sql.*;

/**
 * ConnectionPool with feature-flag-gated connection lifecycle hooks.
 * Supports pluggable lifecycle listeners that can perform cleanup/audit operations.
 */
public class ManagedConnectionPool {

    private final ConcurrentHashMap<String, PooledConnection> activeConnections = new ConcurrentHashMap<>();
    private final AtomicReference<FeatureFlags> flags = new AtomicReference<>(new FeatureFlags());
    private final ConnectionLifecycleListener lifecycleListener;
    private final Object poolLock = new Object();
    private volatile boolean draining = false;

    public ManagedConnectionPool(ConnectionLifecycleListener listener) {
        this.lifecycleListener = listener;
    }

    public void updateFlags(FeatureFlags newFlags) {
        flags.set(newFlags);
    }

    public PooledConnection acquire(String clientId) throws SQLException {
        synchronized (poolLock) {
            if (draining) throw new SQLException("Pool is draining");
            PooledConnection conn = createConnection(clientId);
            activeConnections.put(clientId, conn);
            if (flags.get().isEnabled("lifecycle.hooks")) {
                lifecycleListener.onAcquire(conn, this);
            }
            return conn;
        }
    }

    public void release(String clientId) throws SQLException {
        PooledConnection conn;
        synchronized (poolLock) {
            conn = activeConnections.remove(clientId);
            if (conn == null) return;
            conn.markReleased();
        }
        // Notify listener outside lock to avoid holding pool lock during callbacks
        if (flags.get().isEnabled("lifecycle.hooks")) {
            lifecycleListener.onRelease(conn, this);
        }
    }

    /**
     * Drain all connections - used during graceful shutdown.
     * Iterates active connections and releases them with audit logging.
     */
    public void drainAll() throws SQLException {
        synchronized (poolLock) {
            draining = true;
        }
        // Snapshot keys to avoid CME
        for (String clientId : activeConnections.keySet().toArray(new String[0])) {
            release(clientId);
        }
    }

    /**
     * Re-acquire a connection for a client that previously released one.
     * Used by the lifecycle listener for connection migration scenarios.
     */
    public PooledConnection reacquireForMigration(String clientId) throws SQLException {
        // This method is callable from lifecycle callbacks
        synchronized (poolLock) {
            if (activeConnections.containsKey(clientId)) {
                return activeConnections.get(clientId);
            }
            PooledConnection conn = createConnection(clientId);
            activeConnections.put(clientId, conn);
            return conn;
        }
    }

    public int getActiveCount() {
        return activeConnections.size();
    }

    public boolean isDraining() {
        return draining;
    }

    private PooledConnection createConnection(String clientId) {
        return new PooledConnection(clientId, System.nanoTime());
    }

    // --- Inner classes ---

    public static class PooledConnection {
        private final String clientId;
        private final long createdAt;
        private volatile boolean released = false;
        private volatile boolean closed = false;

        public PooledConnection(String clientId, long createdAt) {
            this.clientId = clientId;
            this.createdAt = createdAt;
        }

        public void markReleased() { this.released = true; }
        public boolean isReleased() { return released; }
        public String getClientId() { return clientId; }
        public long getCreatedAt() { return createdAt; }

        public void close() {
            if (!closed) {
                closed = true;
                // actual connection close logic
            }
        }

        public boolean isClosed() { return closed; }
    }

    public static class FeatureFlags {
        private final ConcurrentHashMap<String, Boolean> flagMap = new ConcurrentHashMap<>();

        public FeatureFlags() {
            flagMap.put("lifecycle.hooks", true);
            flagMap.put("audit.logging", true);
            flagMap.put("migration.enabled", true);
        }

        public boolean isEnabled(String flag) {
            return flagMap.getOrDefault(flag, false);
        }

        public void setFlag(String flag, boolean value) {
            flagMap.put(flag, value);
        }
    }

    public interface ConnectionLifecycleListener {
        void onAcquire(PooledConnection conn, ManagedConnectionPool pool) throws SQLException;
        void onRelease(PooledConnection conn, ManagedConnectionPool pool) throws SQLException;
    }

    /**
     * Default listener that performs audit logging and optional connection migration.
     */
    public static class AuditingLifecycleListener implements ConnectionLifecycleListener {
        @Override
        public void onAcquire(PooledConnection conn, ManagedConnectionPool pool) {
            // Audit log: connection acquired
            System.out.println("AUDIT: acquired " + conn.getClientId());
        }

        @Override
        public void onRelease(PooledConnection conn, ManagedConnectionPool pool) throws SQLException {
            // When migration is enabled, re-acquire connection for failover tracking
            if (pool.flags.get().isEnabled("migration.enabled")) {
                PooledConnection migrated = pool.reacquireForMigration(conn.getClientId());
                System.out.println("AUDIT: migrated " + migrated.getClientId());
            }
        }
    }
}
